import{_ as l,C as s,o,c as i,a2 as e,b as n,w as r,a as E,E as B,a3 as d}from"./chunks/framework.CZGNF-7T.js";const p=JSON.parse('{"title":"워크스페이스","description":"","frontmatter":{},"headers":[],"relativePath":"work-manage/workspace.md","filePath":"work-manage/workspace.md","lastUpdated":1788519155000}'),C={name:"work-manage/workspace.md"};function A(g,a,c,h,m,u){const t=s("Mermaid");return o(),i("div",null,[a[1]||(a[1]=e('<h1 id="워크스페이스" tabindex="-1">워크스페이스 <a class="header-anchor" href="#워크스페이스" aria-label="Permalink to &quot;워크스페이스&quot;">​</a></h1><blockquote><p>**워크스페이스 (Workspace)**는 부동산 개발사업, 본사 경영지원, 일반 협업 등 모든 업무와 회의, 문서, 로드맵을 통합 관리하는 <strong>IBS의 최상위 협업 공간</strong>입니다.</p></blockquote><h2 id="_1-화면-개요" tabindex="-1">1. 화면 개요 <a class="header-anchor" href="#_1-화면-개요" aria-label="Permalink to &quot;1. 화면 개요&quot;">​</a></h2><p>워크스페이스 목록 화면은 사용자가 참여 중이거나 열람 권한이 있는 모든 워크스페이스를 <strong>보드 (카드)</strong> 또는 <strong>목록 (테이블)</strong> 형태로 제공합니다.</p><p>상단의 통합 검색 바, 필터 도구, 우측의 **저장 쿼리 (Saved Queries)**를 활용하여 원하는 워크스페이스를 신속하게 탐색할 수 있습니다.</p>',5)),(o(),n(d,null,{default:r(()=>[B(t,{id:"mermaid-17",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22%F0%9F%8F%A2%20%EC%9B%8C%ED%81%AC%EC%8A%A4%ED%8E%98%EC%9D%B4%EC%8A%A4%20%EB%AA%A9%EB%A1%9D%22%5D%20--%3E%20B%5B%22%EB%B3%B4%EB%93%9C%20%EB%B3%B4%EA%B8%B0%3A%20%EC%B9%B4%EB%93%9C%ED%98%95%20%EC%8B%9C%EA%B0%81%ED%99%94%22%5D%0A%20%20%20%20A%20--%3E%20C%5B%22%EB%AA%A9%EB%A1%9D%20%EB%B3%B4%EA%B8%B0%3A%20%EA%B3%84%EC%B8%B5%ED%98%95%20%ED%85%8C%EC%9D%B4%EB%B8%94%20%26%20%EC%BB%AC%EB%9F%BC%20%EC%84%A0%ED%83%9D%22%5D%0A%0A%20%20%20%20A%20--%3E%20D%5B%22%EC%9A%B0%EC%B8%A1%20%EC%82%AC%EC%9D%B4%EB%93%9C%EB%B0%94%3A%20%EC%A0%80%EC%9E%A5%20%EC%BF%BC%EB%A6%AC%22%5D%0A%0A%20%20%20%20B%20%26%20C%20--%3E%20E%5B%22%EA%B0%9C%EB%B3%84%20%EC%9B%8C%ED%81%AC%EC%8A%A4%ED%8E%98%EC%9D%B4%EC%8A%A4%20%EC%A7%84%EC%9E%85%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22%EA%B0%9C%EC%9A%94%20%2F%20%EC%97%85%EB%AC%B4%20%2F%20%ED%9A%8C%EC%9D%98%EB%A1%9D%20%2F%20%EB%A1%9C%EB%93%9C%EB%A7%B5%20%2F%20%EC%BA%98%EB%A6%B0%EB%8D%94%20%2F%20%EB%AC%B8%EC%84%9C%20%2F%20%EA%B2%8C%EC%8B%9C%ED%8C%90%20%2F%20%EC%84%A4%EC%A0%95%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="_2-주요-기능-안내" tabindex="-1">2. 주요 기능 안내 <a class="header-anchor" href="#_2-주요-기능-안내" aria-label="Permalink to &quot;2. 주요 기능 안내&quot;">​</a></h2><h3 id="🔍-워크스페이스-검색-및-조건-필터링" tabindex="-1">🔍 워크스페이스 검색 및 조건 필터링 <a class="header-anchor" href="#🔍-워크스페이스-검색-및-조건-필터링" aria-label="Permalink to &quot;🔍 워크스페이스 검색 및 조건 필터링&quot;">​</a></h3><ul><li><strong>키워드 검색</strong>: 상단 검색창을 통해 워크스페이스 이름 또는 식별자로 즉시 검색합니다.</li><li><strong>상태 및 공개 필터</strong>: 진행 중 (<code>진행</code>), 종료 (<code>잠금보관</code>), 공개 여부 (<code>공개/비공개</code>), 소속 멤버 여부 등의 세부 조건으로 필터링할 수 있습니다.</li><li><strong>사용자 저장 쿼리 (Saved Queries)</strong>: 우측 패널에서 자주 사용하는 검색 조건을 저장하여 원클릭으로 호출하거나, 권한 (<code>PROJECT_PUB_QUERY</code>)에 따라 전사 구성원과 공유할 수 있습니다.</li></ul><h3 id="🖼️-보기-방식-전환-보드-목록" tabindex="-1">🖼️ 보기 방식 전환 (보드 / 목록) <a class="header-anchor" href="#🖼️-보기-방식-전환-보드-목록" aria-label="Permalink to &quot;🖼️ 보기 방식 전환 (보드 / 목록)&quot;">​</a></h3><p>상단 옵션 영역에서 원하는 뷰 방식을 선택할 수 있으며, 선택한 설정은 브라우저에 자동 보존됩니다.</p><ul><li><strong>보드 (Board) 방식</strong>: <ul><li>각 워크스페이스를 독립된 카드로 시각화하여 주요 정보 (설명, 담당자, 하위 워크스페이스 수)를 빠르게 파악할 수 있습니다.</li><li>반응형 레이아웃이 적용되어 화면 크기 (PC, 태블릿, 모바일)에 맞춰 카드 배열이 동적으로 최적화됩니다.</li></ul></li><li><strong>목록 (List) 방식</strong>: <ul><li>워크스페이스 이름, 식별자, 생성일, 공개 여부 등을 정돈된 테이블로 제공합니다.</li><li><strong>계층 구조 시각화</strong>: 상위 워크스페이스와 하위 (Sub) 워크스페이스의 종속 관계가 들여쓰기와 트리 구조로 명확히 표시됩니다.</li><li><strong>테이블 컬럼 선택자 (Column Selector)</strong>: <code>[항목 선택]</code> 도구를 통해 표시할 테이블 컬럼을 사용자가 직접 구성할 수 있습니다.</li></ul></li></ul><h3 id="➕-새-워크스페이스-생성-권한자-전용" tabindex="-1">➕ 새 워크스페이스 생성 (권한자 전용) <a class="header-anchor" href="#➕-새-워크스페이스-생성-권한자-전용" aria-label="Permalink to &quot;➕ 새 워크스페이스 생성 (권한자 전용)&quot;">​</a></h3><ul><li>워크스페이스 생성 권한 (<code>PROJECT_CREATE</code>)이 부여된 역할 (Role)을 가진 사용자에게만 우측 상단에 <strong>[새 워크스페이스]</strong> 버튼이 노출됩니다.</li><li>일반 구성원은 초대받은 워크스페이스 내에서만 활동이 가능하며, 생성이 필요한 경우 관리 부서에 요청합니다.</li></ul><h3 id="🏷️-아이콘-및-범례-안내" tabindex="-1">🏷️ 아이콘 및 범례 안내 <a class="header-anchor" href="#🏷️-아이콘-및-범례-안내" aria-label="Permalink to &quot;🏷️ 아이콘 및 범례 안내&quot;">​</a></h3><p>화면 하단에서 워크스페이스의 상태를 나타내는 범례를 확인할 수 있습니다.</p><ul><li><i class="mdi mdi-account-tag text-success"></i> <strong>내 워크스페이스</strong>: 본인이 관리자 또는 참여 구성원으로 등록된 공간</li><li><i class="mdi mdi-bookmark text-info"></i> <strong>내 북마크</strong>: 자주 방문하여 즐겨찾기로 등록해 둔 공간</li><li>🔒 <strong>잠금보관 (Archived)</strong>: 사업 종료 또는 보관 처리되어 수정이 제한된 읽기 전용 공간</li></ul><h2 id="_3-워크스페이스-내부-주요-메뉴-안내" tabindex="-1">3. 워크스페이스 내부 주요 메뉴 안내 <a class="header-anchor" href="#_3-워크스페이스-내부-주요-메뉴-안내" aria-label="Permalink to &quot;3. 워크스페이스 내부 주요 메뉴 안내&quot;">​</a></h2><p>특정 워크스페이스를 클릭하여 진입하면 다음 8대 핵심 협업 도구를 이용할 수 있습니다.</p><ol><li><strong>[개요 (Overview)]</strong>: 워크스페이스 요약 정보, 서브 프로젝트 목록, 미해결 이슈 현황</li><li><strong><a href="/work-manage/issue.html">업무 (Issues)</a></strong>: 이슈 트래커, 상태별 업무 목록, 간트차트</li><li><strong><a href="/work-manage/meeting.html">회의록 (Meetings)</a></strong>: 의제 (Agenda), 의사결정 사항, 액션아이템 연동 관리</li><li><strong><a href="/work-manage/roadmap.html">로드맵 (Roadmap)</a></strong>: 버전 및 마일스톤별 달성률 추적</li><li><strong><a href="/work-manage/calendar.html">캘린더 (Calendar)</a></strong>: 마감일 및 회의 일정 달력 시각화</li><li><strong><a href="/work-manage/docs.html">문서 (Documents)</a></strong>: 워크스페이스 공유 문서 보관소</li><li><strong><a href="/work-manage/forum.html">게시판 (Forums)</a></strong>: 자유로운 의견 교환 및 질의응답 포럼</li><li><strong><a href="/work-manage/settings.html">설정 (Settings)</a></strong>: 워크스페이스 기본 정보, 멤버 관리, 모듈 활성화 설정</li></ol><h2 id="_4-이용-팁" tabindex="-1">4. 이용 팁 <a class="header-anchor" href="#_4-이용-팁" aria-label="Permalink to &quot;4. 이용 팁&quot;">​</a></h2><ul><li>전체적인 <strong>상위-하위 워크스페이스 트리 구조</strong>를 파악하고 싶을 때는 <strong>&#39;목록&#39;</strong> 방식을, 요약 정보를 훑어볼 때는 <strong>&#39;보드&#39;</strong> 방식을 권장합니다.</li><li>자주 방문하는 핵심 프로젝트는 카드 우측 상단의 **북마크 (별표/리본)**를 클릭해 두면 빠르게 접근할 수 있습니다.</li></ul>',16))])}const D=l(C,[["render",A]]);export{p as __pageData,D as default};
